│    ├─ 发送寄存器地址 0x03F1 (低字节)                          │
│    └─ 读取数据 (期望值: 0x83)                                 │
└─────────────────────────────────────────────────────────────┘
```

## 详细配置步骤

### 1. 引脚复用配置 (Pinmux)

**文件：** `build/boards/cv181x/sg2002_milkv_duo256m_glibc_arm64_sd/u-boot/cvi_board_init.c`

```c
int cvi_board_init(void)
{
    // Camera 引脚配置
    PINMUX_CONFIG(PAD_MIPI_TXM1, IIC2_SDA);    // I2C2 数据线
    PINMUX_CONFIG(PAD_MIPI_TXP1, IIC2_SCL);    // I2C2 时钟线
    PINMUX_CONFIG(PAD_MIPI_TXP0, CAM_MCLK0);   // 摄像头主时钟 (24MHz)
    PINMUX_CONFIG(PAD_MIPI_TXP2, XGPIOC_17);   // 传感器复位引脚

    return 0;
}
```

**引脚功能说明：**

| 引脚 | 功能 | 说明 |
|------|------|------|
| PAD_MIPI_TXM1 | IIC2_SDA | I2C2 数据线 |
| PAD_MIPI_TXP1 | IIC2_SCL | I2C2 时钟线 |
| PAD_MIPI_TXP0 | CAM_MCLK0 | 摄像头主时钟输出 (24MHz) |
| PAD_MIPI_TXP2 | XGPIOC_17 | 传感器复位控制 |

### 2. 传感器电源上电

GC2083 需要三路电源：

| 电源 | 电压 | 用途 | 说明 |
|------|------|------|------|
| **AVDD** | 2.8V | 模拟电源 | 传感器模拟电路 |
| **DVDD** | 1.2V | 数字电源 | 传感器数字电路 |
| **DOVDD** | 1.8V | IO 电源 | I2C/MIPI 接口 |

**上电时序：**
```
电源上电顺序:
1. DVDD (1.2V) 先上电
2. DOVDD (1.8V) 次上电
3. AVDD (2.8V) 最后上电

时序要求:
- 各电源上电间隔: 1-5ms
- 上电完成后等待: 10ms
```

**代码示例：**
```c
void gc2083_power_on(void)
{
    // 1. 使能 DVDD (1.2V)
    gpio_set_value(DVDD_GPIO, 1);
    usleep(2000);  // 2ms

    // 2. 使能 DOVDD (1.8V)
    gpio_set_value(DOVDD_GPIO, 1);
    usleep(2000);  // 2ms

    // 3. 使能 AVDD (2.8V)
    gpio_set_value(AVDD_GPIO, 1);
    usleep(5000);  // 5ms

    // 4. 等待电源稳定
    usleep(10000); // 10ms
}
```

### 3. MCLK 时钟输出配置

GC2083 需要外部时钟输入 (MCLK/XCLK)，通常为 24MHz。

**配置代码：**
```c
// 配置 CAM_MCLK0 引脚输出 24MHz 时钟
PINMUX_CONFIG(PAD_MIPI_TXP0, CAM_MCLK0);

// 时钟频率配置
struct combo_dev_attr_s gc2083_rx_attr = {
    .mclk = {
        .cam = 0,                    // 使用 CAM_MCLK0
        .freq = CAMPLL_FREQ_24M,     // 24MHz
    },
};
```

**时钟配置寄存器：**
```c
// 时钟源配置
#define REG_CAM_MCLK_SRC    0x03002080  // MCLK 时钟源选择
#define REG_CAM_MCLK_DIV    0x03002084  // MCLK 分频系数

// 配置 MCLK = 24MHz
// 假设时钟源 = 96MHz
// 分频系数 = 96MHz / 24MHz = 4
```

### 4. 传感器复位控制

**复位时序：**
```
RESET 引脚时序:
        ┌─────────────────────────────────────────────┐
        │                                             │
    ────┘                                             └────
        ↑     ↑           ↑                           ↑
        │     │           │                           │
      拉低  10ms延时    拉高                        20ms延时
        │                                             │
        └──────────── 复位过程 ────────────────────────┘
                                                   (传感器就绪)
```

**代码实现：**
```c
void gc2083_reset(void)
{
    // 1. 配置复位引脚为 GPIO 输出
    PINMUX_CONFIG(PAD_MIPI_TXP2, XGPIOC_17);
    gpio_direction_output(RESET_GPIO, 1);

    // 2. 拉低复位引脚
    gpio_set_value(RESET_GPIO, 0);
    usleep(10000);  // 10ms

    // 3. 拉高复位引脚
    gpio_set_value(RESET_GPIO, 1);
    usleep(20000);  // 20ms (等待传感器初始化完成)
}
```

**设备树配置：**
```dts
// 文件: build/boards/cv181x/sg2002_milkv_duo256m_glibc_arm64_sd/dts_arm64/sg2002_milkv_duo256m_glibc_arm64_sd.dts

&mipi_rx {
    snsr-reset = <&portc 17 GPIO_ACTIVE_LOW>;  // 复位引脚
};
```

### 5. I2C2 控制器初始化

**完整初始化代码：**
```c
void i2c2_init(void)
{
    u32 reg;

    // ========================================
    // 5.1 使能 I2C2 时钟
    // ========================================

    // 选择时钟源 (osc = 25MHz)
    reg = readl(0x03002080);  // REG_CLK_BYP_0
    reg |= (1 << 31);         // 旁路模式，使用 osc
    writel(reg, 0x03002080);

    // 设置分频系数 (不分频)
    reg = readl(0x03002104);  // REG_DIV_CLK_I2C
    reg &= ~(0xF << 16);     // 清除分频位
    reg |= (1 << 16);        // 分频系数 = 1
    writel(reg, 0x03002104);

    // 使能 CLK_I2C
    reg = readl(0x0300200C);  // REG_CLK_EN_3
    reg |= (1 << 7);          // 使能 CLK_I2C
    writel(reg, 0x0300200C);

    // ========================================
    // 5.2 解除 I2C2 复位
    // ========================================
    // 注意: 需要通过 reset 框架实现
    // reset_control_deassert(rst_i2c2);

    // ========================================
    // 5.3 配置 I2C2 控制器
    // ========================================

    // 禁用 I2C2
    writel(0, 0x04020000 + 0x6C);  // IC_ENABLE = 0

    // 配置模式: 主模式 + 标准速度 (100kHz) + 重启使能
    reg = 0x01;      // 主模式
    reg |= 0x02;     // 标准速度 (100kHz)
    reg |= 0x20;     // 重启使能
    reg |= 0x40;     // 禁用从模式
    writel(reg, 0x04020000 + 0x00);  // IC_CON

    // 配置 SCL 时序 (100kHz, I2C时钟=25MHz)
    // HCNT = (25MHz × 4.0µs) = 100
    // LCNT = (25MHz × 4.7µs) = 118
    writel(100, 0x04020000 + 0x14);  // IC_SS_SCL_HCNT
    writel(118, 0x04020000 + 0x18);  // IC_SS_SCL_LCNT

    // 配置 SDA 保持时间
    writel(0x1E, 0x04020000 + 0x7C);  // IC_SDA_HOLD

    // 使能 I2C2
    writel(1, 0x04020000 + 0x6C);  // IC_ENABLE = 1
}
```

### 6. 读取芯片 ID

**完整读取代码：**
```c
#define GC2083_I2C_ADDR      0x37
#define GC2083_CHIP_ID_H     0x03F0
#define GC2083_CHIP_ID_L     0x03F1
#define GC2083_CHIP_ID       0x2083

u16 read_gc2083_chip_id(void)
{
    u32 reg;
    u8 id_h, id_l;

    // 1. 禁用 I2C2
    writel(0, 0x04020000 + 0x6C);

    // 2. 设置目标地址 (GC2083: 0x37)
    writel(GC2083_I2C_ADDR, 0x04020000 + 0x04);  // IC_TAR

    // 3. 使能 I2C2
    writel(1, 0x04020000 + 0x6C);

    // 4. 读取芯片 ID 高字节 (0x03F0)
    // 发送寄存器地址高字节
    writel(0x03, 0x04020000 + 0x10);  // 写命令

    // 发送寄存器地址低字节
    writel(0xF0, 0x04020000 + 0x10);  // 写命令

    // 发送读命令 + 停止位
    writel(0x100 | 0x200, 0x04020000 + 0x10);  // 读命令 + 停止位

    // 等待数据接收 (RX FIFO 非空)
    while (!(readl(0x04020000 + 0x70) & 0x08))
        ;

    // 读取数据
    id_h = readl(0x04020000 + 0x10) & 0xFF;

    // 5. 读取芯片 ID 低字节 (0x03F1)
    // 发送寄存器地址高字节
    writel(0x03, 0x04020000 + 0x10);  // 写命令

    // 发送寄存器地址低字节
    writel(0xF1, 0x04020000 + 0x10);  // 写命令

    // 发送读命令 + 停止位
    writel(0x100 | 0x200, 0x04020000 + 0x10);  // 读命令 + 停止位

    // 等待数据接收 (RX FIFO 非空)
    while (!(readl(0x04020000 + 0x70) & 0x08))
        ;

    // 读取数据
    id_l = readl(0x04020000 + 0x10) & 0xFF;

    // 6. 返回芯片 ID
    return (id_h << 8) | id_l;  // 期望值: 0x2083
}
```

## 完整初始化流程示例

```c
#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

// GPIO 操作函数
void gpio_export(int gpio)
{
    char cmd[100];
    sprintf(cmd, "echo %d > /sys/class/gpio/export", gpio);
    system(cmd);
}

void gpio_direction_output(int gpio, int value)
{
    char cmd[100];
    sprintf(cmd, "echo out > /sys/class/gpio/gpio%d/direction", gpio);
    system(cmd);
    sprintf(cmd, "echo %d > /sys/class/gpio/gpio%d/value", value, gpio);
    system(cmd);
}

void gpio_set_value(int gpio, int value)
{
    char cmd[100];
    sprintf(cmd, "echo %d > /sys/class/gpio/gpio%d/value", value, gpio);
    system(cmd);
}

int main()
{
    int fd;
    int ret;
    unsigned char buf[4];
    unsigned char id_h, id_l;
    unsigned short chip_id;

    printf("=== GC2083 芯片 ID 读取程序 ===\n\n");

    // ========================================
    // 第一步: 配置引脚复用
    // ========================================
    printf("1. 配置引脚复用...\n");
    system("devmem 0x03001c30 32 0x01");  // IIC2_SDA
    system("devmem 0x03001c34 32 0x01");  // IIC2_SCL
    system("devmem 0x03001c2c 32 0x01");  // CAM_MCLK0
    system("devmem 0x03001c38 32 0x00");  // XGPIOC_17 (复位)
    printf("   引脚配置完成\n\n");

    // ========================================
    // 第二步: 传感器电源上电
    // ========================================
    printf("2. 传感器电源上电...\n");

    // 假设使用 GPIO 控制电源
    // 需要根据实际硬件连接修改
    // gpio_export(DVDD_GPIO);
    // gpio_export(DOVDD_GPIO);
    // gpio_export(AVDD_GPIO);

    // 上电顺序: DVDD -> DOVDD -> AVDD
    // gpio_set_value(DVDD_GPIO, 1);   // DVDD 1.2V
    // usleep(2000);
    // gpio_set_value(DOVDD_GPIO, 1);  // DOVDD 1.8V
    // usleep(2000);
    // gpio_set_value(AVDD_GPIO, 1);   // AVDD 2.8V
    // usleep(5000);

    printf("   电源上电完成\n\n");

    // ========================================
    // 第三步: 配置 MCLK 时钟输出
    // ========================================
    printf("3. 配置 MCLK 时钟输出 (24MHz)...\n");

    // 配置 MCLK 时钟源和分频
    // 假设时钟源 = 96MHz, 分频系数 = 4, 输出 = 24MHz
    system("devmem 0x03002080 32 0x00000000");  // 选择时钟源
    system("devmem 0x03002084 32 0x00000004");  // 分频系数 = 4
    system("devmem 0x0300200C 32 0x00000001");  // 使能 MCLK

    printf("   MCLK 配置完成 (24MHz)\n\n");

    // ========================================
    // 第四步: 传感器复位
    // ========================================
    printf("4. 传感器复位...\n");

    // 配置复位引脚
    gpio_export(17);  // GPIOC_17
    gpio_direction_output(17, 1);

    // 复位时序
    gpio_set_value(17, 0);  // 拉低
    usleep(10000);           // 10ms
    gpio_set_value(17, 1);  // 拉高
    usleep(20000);           // 20ms

    printf("   复位完成\n\n");

    // ========================================
    // 第五步: I2C2 控制器初始化
    // ========================================
    printf("5. I2C2 控制器初始化...\n");

    // 5.1 使能 I2C2 时钟
    system("devmem 0x03002080 32 0x80000000");  // 选择 osc (25MHz)
    system("devmem 0x03002104 32 0x00010000");  // 分频系数 = 1
    system("devmem 0x0300200C 32 0x00000080");  // 使能 CLK_I2C

    // 5.2 解除 I2C2 复位
    // 注意: 实际需要通过 reset 框架实现

    // 5.3 配置 I2C2 控制器
    fd = open("/dev/i2c-2", O_RDWR);
    if (fd < 0) {
        perror("open i2c-2 failed");
        return -1;
    }

    // 设置 I2C 从设备地址
    ret = ioctl(fd, I2C_SLAVE_FORCE, 0x37);
    if (ret < 0) {
        perror("set i2c slave address failed");
        close(fd);
        return -1;
    }

    printf("   I2C2 初始化完成\n\n");

    // ========================================
    // 第六步: 读取芯片 ID
    // ========================================
    printf("6. 读取 GC2083 芯片 ID...\n");

    // 等待传感器稳定
    usleep(50);

    // 读取芯片 ID 高字节 (0x03F0)
    buf[0] = (0x03F0 >> 8) & 0xFF;  // 0x03
    buf[1] = 0x03F0 & 0xFF;          // 0xF0
    write(fd, buf, 2);
    read(fd, &id_h, 1);

    // 读取芯片 ID 低字节 (0x03F1)
    buf[0] = (0x03F1 >> 8) & 0xFF;  // 0x03
    buf[1] = 0x03F1 & 0xFF;          // 0xF1
    write(fd, buf, 2);
    read(fd, &id_l, 1);

    // 组合芯片 ID
    chip_id = (id_h << 8) | id_l;

    printf("   读取到芯片 ID: 0x%04X\n", chip_id);
    printf("   期望芯片 ID: 0x%04X\n", GC2083_CHIP_ID);

    if (chip_id == GC2083_CHIP_ID) {
        printf("\n   ✓ GC2083 传感器检测成功！\n");
    } else {
        printf("\n   ✗ GC2083 传感器检测失败！\n");
    }

    // ========================================
    // 清理
    // ========================================
    close(fd);

    return 0;
}
```

## 总结

要通过 I2C 读取 GC2083 芯片 ID，除了初始化 I2C2 控制器外，还需要：

| 步骤 | 工作内容 | 关键点 |
|------|---------|--------|
| **1. 引脚复用** | 配置 I2C2 SDA/SCL、MCLK、RESET 引脚 | 确保引脚功能正确 |
| **2. 电源上电** | AVDD(2.8V)、DVDD(1.2V)、DOVDD(1.8V) | 按顺序上电，注意时序 |
| **3. MCLK 输出** | 配置 24MHz 时钟输出 | 传感器需要外部时钟 |
| **4. 复位控制** | RESET 引脚拉低-延时-拉高 | 等待传感器初始化完成 |
| **5. I2C 初始化** | 使能时钟、配置模式、设置时序 | 100kHz 标准模式 |
| **6. 读取 ID** | 读取 0x03F0 和 0x03F1 寄存器 | 组合为 16 位芯片 ID |

**关键注意事项：**
1. **电源时序**：必须按照 DVDD → DOVDD → AVDD 顺序上电
2. **复位时序**：RESET 拉低至少 10ms，拉高后等待 20ms
3. **MCLK 必须提供**：传感器需要 24MHz 外部时钟才能工作
4. **I2C 地址**：GC2083 的 I2C 地址为 0x37 (7位地址)
5. **等待时间**：复位后需要等待足够时间让传感器初始化完成

