159	static void cv181x_ephy_id_init(void)
160	{
161		// set rg_ephy_apb_rw_sel 0x0804@[0]=1/APB by using APB interface
162		mmio_write_32(0x03009804, 0x0001);
163	
164		// Release 0x0800[0]=0/shutdown
165		mmio_write_32(0x03009800, 0x0900);
166	
167		// Release 0x0800[2]=1/dig_rst_n, Let mii_reg can be accessabile
168		mmio_write_32(0x03009800, 0x0904);
169	
170		// ANA INIT (PD/EN), switch to MII-page5
171		mmio_write_32(0x0300907c, 0x0500);
172		// Release ANA_PD p5.0x10@[13:8] = 6'b001100
173		mmio_write_32(0x03009040, 0x0c00);
174		// Release ANA_EN p5.0x10@[7:0] = 8'b01111110
175		mmio_write_32(0x03009040, 0x0c7e);
176	
177		// Wait PLL_Lock, Lock_Status p5.0x12@[15] = 1
178		//mdelay(1);
179	
180		// Release 0x0800[1] = 1/ana_rst_n
181		mmio_write_32(0x03009800, 0x0906);
182	
183		// ANA INIT
184		// @Switch to MII-page5
185		mmio_write_32(0x0300907c, 0x0500);
186	
187		// PHY_ID
188		mmio_write_32(0x03009008, 0x0043);
189		mmio_write_32(0x0300900c, 0x5649);
