现在我已经了解了 milkv_duos 的板级支持包结构，让我为您规划一个完整的实现方案。

## 实现规划

### 1. 项目结构规划

```
/home/wsb/duo-buildroot-sdk-v2/build/boards/cv181x/sg2000_milkv_duos_musl_riscv64_sd/
├── u-boot/
│   ├── cvi_board_init.c          # 板级初始化文件 (需要修改)
│   ├── cvitek.h                  # 板级头文件
│   └── gc2083_sensor_detect.c    # 新增: GC2083 传感器检测程序
```

### 2. 功能需求

1. **传感器电源控制**：控制 AVDD、DVDD、DOVDD 电源
2. **MCLK 时钟输出**：配置 24MHz 摄像头主时钟
3. **复位控制**：控制传感器复位引脚
4. **I2C 通信**：通过 I2C2 读取芯片 ID
5. **日志输出**：详细的调试日志

### 3. 代码实现规划

#### 3.1 新增文件：gc2083_sensor_detect.c

```c
// 文件路径: build/boards/cv181x/sg2000_milkv_duos_musl_riscv64_sd/u-boot/gc2083_sensor_detect.c

#include <common.h>
#include <i2c.h>
#include <linux/delay.h>
#include <asm/io.h>

// ========================================
// GC2083 寄存器定义
// ========================================
#define GC2083_I2C_ADDR         0x37
#define GC2083_I2C_BUS          2
#define GC2083_CHIP_ID_H_REG    0x03F0
#define GC2083_CHIP_ID_L_REG    0x03F1
#define GC2083_CHIP_ID          0x2083

// ========================================
// 时钟寄存器定义
// ========================================
#define REG_CLK_EN_3            0x0300200C
#define REG_DIV_CLK_I2C         0x03002104
#define REG_CLK_BYP_0           0x03002080

// ========================================
// GPIO 寄存器定义
// ========================================
#define GPIO_BASE               0x03020000
#define GPIO_OEN                0x04
#define GPIO_OUTPUT             0x00

// ========================================
// 日志级别定义
// ========================================
#define LOG_LEVEL_ERROR         0
#define LOG_LEVEL_WARN          1
#define LOG_LEVEL_INFO          2
#define LOG_LEVEL_DEBUG         3

#define GC2083_LOG_LEVEL        LOG_LEVEL_DEBUG

#define gc2083_log(level, fmt, ...) \
    do { \
        if (level <= GC2083_LOG_LEVEL) { \
            const char *level_str[] = {"ERROR", "WARN", "INFO", "DEBUG"}; \
            printf("[GC2083][%s] " fmt "\n", level_str[level], ##__VA_ARGS__); \
        } \
    } while (0)

// ========================================
// 电源控制引脚定义 (根据实际硬件修改)
// ========================================
#define DVDD_GPIO_PORT          0   // GPIOA
#define DVDD_GPIO_PIN           1
#define DOVDD_GPIO_PORT         0   // GPIOA
#define DOVDD_GPIO_PIN          4
#define AVDD_GPIO_PORT          0   // GPIOA
#define AVDD_GPIO_PIN           6
#define RESET_GPIO_PORT         2   // GPIOC
#define RESET_GPIO_PIN          17

// ========================================
// GPIO 操作函数
// ========================================
static void gpio_set_output(int port, int pin, int value)
{
    uint32_t base = GPIO_BASE + port * 0x1000;
    uint32_t reg;

    // 设置为输出模式
    reg = mmio_read_32(base + GPIO_OEN);
    reg &= ~(1 << pin);
    mmio_write_32(base + GPIO_OEN, reg);

    // 设置输出值
    reg = mmio_read_32(base + GPIO_OUTPUT);
    if (value)
        reg |= (1 << pin);
    else
        reg &= ~(1 << pin);
    mmio_write_32(base + GPIO_OUTPUT, reg);
}

// ========================================
// 时钟配置函数
// ========================================
static int gc2083_clk_init(void)
{
    uint32_t reg;

    gc2083_log(LOG_LEVEL_INFO, "Configuring I2C2 clock...");

    // 1. 选择时钟源 (osc = 25MHz)
    reg = mmio_read_32(REG_CLK_BYP_0);
    reg |= (1 << 31);  // 旁路模式，使用 osc
    mmio_write_32(REG_CLK_BYP_0, reg);
    gc2083_log(LOG_LEVEL_DEBUG, "CLK_BYP_0 = 0x%08X", mmio_read_32(REG_CLK_BYP_0));

    // 2. 设置分频系数 (不分频)
    reg = mmio_read_32(REG_DIV_CLK_I2C);
    reg &= ~(0xF << 16);  // 清除分频位
    reg |= (1 << 16);     // 分频系数 = 1
    mmio_write_32(REG_DIV_CLK_I2C, reg);
    gc2083_log(LOG_LEVEL_DEBUG, "DIV_CLK_I2C = 0x%08X", mmio_read_32(REG_DIV_CLK_I2C));

    // 3. 使能 CLK_I2C
    reg = mmio_read_32(REG_CLK_EN_3);
    reg |= (1 << 7);  // 使能 CLK_I2C
    mmio_write_32(REG_CLK_EN_3, reg);
    gc2083_log(LOG_LEVEL_DEBUG, "CLK_EN_3 = 0x%08X", mmio_read_32(REG_CLK_EN_3));

    gc2083_log(LOG_LEVEL_INFO, "I2C2 clock configured successfully (25MHz)");

    return 0;
}

// ========================================
// 传感器电源控制函数
// ========================================
static int gc2083_power_on(void)
{
    gc2083_log(LOG_LEVEL_INFO, "Powering on GC2083 sensor...");

    // 1. DVDD (1.2V) 上电
    gc2083_log(LOG_LEVEL_DEBUG, "Enabling DVDD (1.2V)...");
    gpio_set_output(DVDD_GPIO_PORT, DVDD_GPIO_PIN, 1);
    mdelay(2);

    // 2. DOVDD (1.8V) 上电
    gc2083_log(LOG_LEVEL_DEBUG, "Enabling DOVDD (1.8V)...");
    gpio_set_output(DOVDD_GPIO_PORT, DOVDD_GPIO_PIN, 1);
    mdelay(2);

    // 3. AVDD (2.8V) 上电
    gc2083_log(LOG_LEVEL_DEBUG, "Enabling AVDD (2.8V)...");
    gpio_set_output(AVDD_GPIO_PORT, AVDD_GPIO_PIN, 1);
    mdelay(5);

    // 4. 等待电源稳定
    gc2083_log(LOG_LEVEL_DEBUG, "Waiting for power stabilization...");
    mdelay(10);

    gc2083_log(LOG_LEVEL_INFO, "GC2083 sensor powered on successfully");

    return 0;
}

// ========================================
// MCLK 配置函数
// ========================================
static int gc2083_mclk_init(void)
{
    gc2083_log(LOG_LEVEL_INFO, "Configuring MCLK (24MHz)...");

    // 配置 MCLK 时钟源和分频
    // 假设时钟源 = 96MHz, 分频系数 = 4, 输出 = 24MHz
    // 需要根据实际时钟源频率调整

    // 使能 MCLK 输出
    // 具体寄存器配置需要参考时钟树文档

    gc2083_log(LOG_LEVEL_INFO, "MCLK configured successfully (24MHz)");

    return 0;
}

// ========================================
// 传感器复位函数
// ========================================
static int gc2083_reset(void)
{
    gc2083_log(LOG_LEVEL_INFO, "Resetting GC2083 sensor...");

    // 1. 拉低复位引脚
    gc2083_log(LOG_LEVEL_DEBUG, "Asserting reset (LOW)...");
    gpio_set_output(RESET_GPIO_PORT, RESET_GPIO_PIN, 0);
    mdelay(10);

    // 2. 拉高复位引脚
    gc2083_log(LOG_LEVEL_DEBUG, "Deasserting reset (HIGH)...");
    gpio_set_output(RESET_GPIO_PORT, RESET_GPIO_PIN, 1);
    mdelay(20);

    gc2083_log(LOG_LEVEL_INFO, "GC2083 sensor reset completed");

    return 0;
}

// ========================================
// I2C 读取芯片 ID 函数
// ========================================
static int gc2083_read_chip_id(uint16_t *chip_id)
{
    struct udevice *dev;
    uint8_t id_h, id_l;
    int ret;

    gc2083_log(LOG_LEVEL_INFO, "Reading GC2083 chip ID via I2C%d...", GC2083_I2C_BUS);

    // 1. 获取 I2C 设备
    ret = i2c_get_chip_for_busnum(GC2083_I2C_BUS, GC2083_I2C_ADDR, 2, &dev);
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Failed to get I2C device: %d", ret);
        return ret;
    }
    gc2083_log(LOG_LEVEL_DEBUG, "I2C device obtained (addr=0x%02X)", GC2083_I2C_ADDR);

    // 2. 读取芯片 ID 高字节
    ret = dm_i2c_read(dev, GC2083_CHIP_ID_H_REG, &id_h, 1);
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Failed to read chip ID high byte: %d", ret);
        return ret;
    }
    gc2083_log(LOG_LEVEL_DEBUG, "Chip ID High = 0x%02X (reg=0x%04X)", id_h, GC2083_CHIP_ID_H_REG);

    // 3. 读取芯片 ID 低字节
    ret = dm_i2c_read(dev, GC2083_CHIP_ID_L_REG, &id_l, 1);
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Failed to read chip ID low byte: %d", ret);
        return ret;
    }
    gc2083_log(LOG_LEVEL_DEBUG, "Chip ID Low = 0x%02X (reg=0x%04X)", id_l, GC2083_CHIP_ID_L_REG);

    // 4. 组合芯片 ID
    *chip_id = (id_h << 8) | id_l;
    gc2083_log(LOG_LEVEL_INFO, "Chip ID = 0x%04X", *chip_id);

    return 0;
}

// ========================================
// GC2083 传感器检测主函数
// ========================================
int gc2083_sensor_detect(void)
{
    uint16_t chip_id;
    int ret;

    gc2083_log(LOG_LEVEL_INFO, "========================================");
    gc2083_log(LOG_LEVEL_INFO, "GC2083 Sensor Detection Start");
    gc2083_log(LOG_LEVEL_INFO, "========================================");

    // 1. 配置时钟
    ret = gc2083_clk_init();
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Clock initialization failed: %d", ret);
        return ret;
    }

    // 2. 传感器上电
    ret = gc2083_power_on();
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Power on failed: %d", ret);
        return ret;
    }

    // 3. 配置 MCLK
    ret = gc2083_mclk_init();
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "MCLK initialization failed: %d", ret);
        return ret;
    }

    // 4. 传感器复位
    ret = gc2083_reset();
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Sensor reset failed: %d", ret);
        return ret;
    }

    // 5. 读取芯片 ID
    ret = gc2083_read_chip_id(&chip_id);
    if (ret) {
        gc2083_log(LOG_LEVEL_ERROR, "Failed to read chip ID: %d", ret);
        return ret;
    }

    // 6. 验证芯片 ID
    gc2083_log(LOG_LEVEL_INFO, "========================================");
    if (chip_id == GC2083_CHIP_ID) {
        gc2083_log(LOG_LEVEL_INFO, "GC2083 Sensor Detected Successfully!");
        gc2083_log(LOG_LEVEL_INFO, "Chip ID: 0x%04X (Expected: 0x%04X)", chip_id, GC2083_CHIP_ID);
    } else {
        gc2083_log(LOG_LEVEL_WARN, "Chip ID Mismatch!");
        gc2083_log(LOG_LEVEL_WARN, "Read: 0x%04X, Expected: 0x%04X", chip_id, GC2083_CHIP_ID);
    }
    gc2083_log(LOG_LEVEL_INFO, "========================================");

    return (chip_id == GC2083_CHIP_ID) ? 0 : -1;
}
