/* GC2083 I2C Configuration */

#define GC2083_I2C_ADDR         0x37
#define GC2083_I2C_BUS          2

/* GC2083 Chip ID Registers */

#define GC2083_CHIP_ID_H_REG    0x03F0
#define GC2083_CHIP_ID_L_REG    0x03F1
#define GC2083_CHIP_ID          0x2083

/* SG2000 I2C2 Controller Base Address */

#define SG2000_I2C2_BASE        0x04020000UL

/* I2C Register Offsets (DesignWare I2C) */

#define I2C_CON                 0x00
#define I2C_TAR                 0x04
#define I2C_DATA_CMD            0x10
#define I2C_SS_SCL_HCNT         0x14
#define I2C_SS_SCL_LCNT         0x18
#define I2C_FS_SCL_HCNT         0x1C
#define I2C_FS_SCL_LCNT         0x20
#define I2C_SDA_HOLD            0x7C
#define I2C_ENABLE              0x6C
#define I2C_STATUS              0x70
#define I2C_ENABLE_STATUS       0x9C

/* I2C Status Register Bits */

#define I2C_STATUS_ACTIVITY     (1 << 0)
#define I2C_STATUS_TFNF         (1 << 1)
#define I2C_STATUS_TFE          (1 << 2)
#define I2C_STATUS_RFNE         (1 << 3)
#define I2C_STATUS_RFF          (1 << 4)

/* I2C Command Register Bits */

#define I2C_CMD_WRITE           0x000
#define I2C_CMD_READ            0x100
#define I2C_CMD_STOP            0x200

/* I2C Control Register Bits */

#define I2C_CON_MASTER          (1 << 0)
#define I2C_CON_SPEED_STD       (1 << 1)
#define I2C_CON_SPEED_FAST      (1 << 2)
#define I2C_CON_RESTART_EN      (1 << 5)
#define I2C_CON_SLAVE_DISABLE   (1 << 6)

/* Clock Registers */

#define SG2000_CLK_BASE         0x03002000UL
#define REG_CLK_EN_3            0x00C
#define REG_DIV_CLK_I2C         0x104
#define REG_CLK_BYP_0           0x080

/* GPIO Registers */

#define SG2000_GPIO_BASE        0x03020000UL
#define GPIO_OEN                0x04
#define GPIO_OUTPUT             0x00

/* Camera MCLK Register */

#define REG_CAM_MCLK_CTRL       0x03002090

/* Log Macros */

#define GC2083_ERR(fmt, ...)    syslog(LOG_ERR, "[GC2083][ERR] " fmt "\n", ##__VA_ARGS__)
#define GC2083_WARN(fmt, ...)   syslog(LOG_WARNING, "[GC2083][WARN] " fmt "\n", ##__VA_ARGS__)
#define GC2083_INFO(fmt, ...)   syslog(LOG_INFO, "[GC2083][INFO] " fmt "\n", ##__VA_ARGS__)
#define GC2083_DEBUG(fmt, ...)  syslog(LOG_DEBUG, "[GC2083][DEBUG] " fmt "\n", ##__VA_ARGS__)

