  /* DVDD Enable (GPIOA_1) */

  { SG2000_GPIO_BASE + 0 * 0x1000, 1 },

  /* DOVDD Enable (GPIOA_4) */

  { SG2000_GPIO_BASE + 0 * 0x1000, 4 },

  /* Reset (GPIOC_17) */

  { SG2000_GPIO_BASE + 2 * 0x1000, 17 },
};

#define PIN_DVDD    0
#define PIN_DOVDD   1
#define PIN_RESET   2

/****************************************************************************
 * Private Functions
