/****************************************************************************
 * Name: gc2083_putc
 *
 * Description:
 *   Output a character directly (bypass syslog for early boot)
 *
 ****************************************************************************/

static void gc2083_putc(char ch)
{
  while ((getreg32(0x04140014) & (1 << 5)) == 0);

  putreg32((uint32_t)ch, 0x04140000);
}

/****************************************************************************
 * Name: gc2083_puts
 *
 * Description:
 *   Output a string directly
 *
 ****************************************************************************/

static void gc2083_puts(const char *str)
{
  while (*str)
    {
      gc2083_putc(*str++);
    }
}

/****************************************************************************
 * Name: gc2083_gpio_set_output
 *
 * Description:
 *   Set a GPIO pin as output with specified value
 *
 ****************************************************************************/

static void gc2083_gpio_set_output(int index, int value)
{
  uint32_t base = g_camera_pins[index].base;
  int      pin  = g_camera_pins[index].pin;
  uint32_t reg;

  /* Set as output (clear OEN bit) */

  reg = getreg32(base + GPIO_OEN);
  reg &= ~(1 << pin);
  putreg32(reg, base + GPIO_OEN);

  /* Set output value */

  reg = getreg32(base + GPIO_OUTPUT);
  if (value)
    {
      reg |= (1 << pin);
    }
  else
    {
      reg &= ~(1 << pin);
    }

  putreg32(reg, base + GPIO_OUTPUT);
}

/****************************************************************************
 * Name: gc2083_delay_ms
 *
 * Description:
 *   Delay in milliseconds
 *
 ****************************************************************************/

static void gc2083_delay_ms(int ms)
{
  up_mdelay(ms);
}

/****************************************************************************
 * Name: gc2083_i2c_init
 *
 * Description:
 *   Initialize I2C2 controller for GC2083 communication
 *
 ****************************************************************************/

static int gc2083_i2c_init(void)
{
  uint32_t reg;
  int      timeout;

  GC2083_INFO("Initializing I2C2 controller...");

  /* Step 1: Enable I2C clock */

  GC2083_DEBUG("Enabling I2C clock...");

  /* Select clock source (osc = 25MHz) */

  reg = getreg32(SG2000_CLK_BASE + REG_CLK_BYP_0);
  reg |= (1 << 31);
  putreg32(reg, SG2000_CLK_BASE + REG_CLK_BYP_0);

  /* Set divider (divide by 1) */

  reg = getreg32(SG2000_CLK_BASE + REG_DIV_CLK_I2C);
  reg &= ~(0xF << 16);
  reg |= (1 << 16);
  putreg32(reg, SG2000_CLK_BASE + REG_DIV_CLK_I2C);

  /* Enable CLK_I2C */

  reg = getreg32(SG2000_CLK_BASE + REG_CLK_EN_3);
  reg |= (1 << 7);
  putreg32(reg, SG2000_CLK_BASE + REG_CLK_EN_3);

  GC2083_DEBUG("I2C clock enabled");

  /* Step 2: Disable I2C controller */

  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);

  /* Wait for controller to be disabled */

  timeout = 1000;
  while (timeout-- > 0)
    {
      reg = getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS);
      if ((reg & 1) == 0)
        {
          break;
        }

      gc2083_delay_ms(1);
    }

  if (timeout <= 0)
    {
      GC2083_ERR("Failed to disable I2C controller");
      return -ETIMEDOUT;
    }

  /* Step 3: Configure I2C controller
   * Master mode + Standard speed (100kHz) + Restart enable + Slave disable
   */

  reg = I2C_CON_MASTER | I2C_CON_SPEED_STD |
        I2C_CON_RESTART_EN | I2C_CON_SLAVE_DISABLE;
  putreg32(reg, SG2000_I2C2_BASE + I2C_CON);

  /* Step 4: Configure SCL timing for 100kHz
   * I2C clock = 25MHz
   * Standard mode: tHIGH = 4.0us, tLOW = 4.7us
   * HCNT = 25MHz * 4.0us = 100
   * LCNT = 25MHz * 4.7us = 117.5 ≈ 118
   */

  putreg32(100, SG2000_I2C2_BASE + I2C_SS_SCL_HCNT);
  putreg32(118, SG2000_I2C2_BASE + I2C_SS_SCL_LCNT);

  /* Step 5: Configure SDA hold time */

  putreg32(0x1E, SG2000_I2C2_BASE + I2C_SDA_HOLD);

  /* Step 6: Enable I2C controller */

  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);

  GC2083_INFO("I2C2 controller initialized successfully");

  return OK;
}

/****************************************************************************
 * Name: gc2083_i2c_wait_tx_empty
 *
 * Description:
 *   Wait for TX FIFO to be empty
 *
 ****************************************************************************/

static int gc2083_i2c_wait_tx_empty(void)
{
  int timeout = 1000;

  while (timeout-- > 0)
    {
      uint32_t status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      if (status & I2C_STATUS_TFE)
        {
          return OK;
        }

      gc2083_delay_ms(1);
    }

  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: gc2083_i2c_wait_rx_data
 *
 * Description:
 *   Wait for data in RX FIFO
 *
 ****************************************************************************/

static int gc2083_i2c_wait_rx_data(void)
{
  int timeout = 1000;

  while (timeout-- > 0)
    {
      uint32_t status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      if (status & I2C_STATUS_RFNE)
        {
          return OK;
        }

      gc2083_delay_ms(1);
    }

  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: gc2083_i2c_read_reg
 *
 * Description:
 *   Read a 16-bit register from GC2083
 *
 ****************************************************************************/

static int gc2083_i2c_read_reg(uint16_t reg_addr, uint8_t *value)
{
  int ret;

  /* Send register address high byte */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

  putreg32(I2C_CMD_WRITE | ((reg_addr >> 8) & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send register address low byte */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

  putreg32(I2C_CMD_WRITE | (reg_addr & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send read command with stop */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

  putreg32(I2C_CMD_READ | I2C_CMD_STOP,
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Wait for data */

  ret = gc2083_i2c_wait_rx_data();
  if (ret < 0)
    {
      GC2083_ERR("Timeout waiting for I2C data");
      return ret;
    }

  /* Read data */

  *value = (uint8_t)(getreg32(SG2000_I2C2_BASE + I2C_DATA_CMD) & 0xFF);

  return OK;
}

/****************************************************************************
 * Name: gc2083_power_on
 *
 * Description:
 *   Power on the GC2083 sensor
 *
 ****************************************************************************/

static int gc2083_power_on(void)
{
  GC2083_INFO("Powering on GC2083 sensor...");

  /* Enable DVDD (1.2V) */

  GC2083_DEBUG("Enabling DVDD (1.2V)...");
  gc2083_gpio_set_output(PIN_DVDD, 1);
  gc2083_delay_ms(2);

  /* Enable DOVDD (1.8V) */

  GC2083_DEBUG("Enabling DOVDD (1.8V)...");
  gc2083_gpio_set_output(PIN_DOVDD, 1);
  gc2083_delay_ms(5);

  GC2083_INFO("GC2083 sensor powered on");

  return OK;
}

/****************************************************************************
 * Name: gc2083_reset
 *
 * Description:
 *   Reset the GC2083 sensor
 *
 ****************************************************************************/

static int gc2083_reset(void)
{
  GC2083_INFO("Resetting GC2083 sensor...");

  /* Assert reset (active low) */

  GC2083_DEBUG("Asserting reset (LOW)...");
  gc2083_gpio_set_output(PIN_RESET, 0);
  gc2083_delay_ms(10);

  /* Deassert reset */

  GC2083_DEBUG("Deasserting reset (HIGH)...");
  gc2083_gpio_set_output(PIN_RESET, 1);
  gc2083_delay_ms(20);

  GC2083_INFO("GC2083 sensor reset completed");

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: gc2083_detect
 *
 * Description:
 *   Detect GC2083 sensor by reading chip ID via I2C
 *
 * Returned Value:
 *   OK if sensor detected successfully, negative errno otherwise
 *
 ****************************************************************************/

int gc2083_detect(void)
{
  uint8_t id_h;
  uint8_t id_l;
  uint16_t chip_id;
  int ret;

  GC2083_INFO("========================================");
  GC2083_INFO("GC2083 Sensor Detection Start");
  GC2083_INFO("========================================");

  /* Step 1: Power on sensor */

  ret = gc2083_power_on();
  if (ret < 0)
    {
      GC2083_ERR("Power on failed: %d", ret);
      return ret;
    }

  /* Step 2: Reset sensor */

  ret = gc2083_reset();
  if (ret < 0)
    {
      GC2083_ERR("Reset failed: %d", ret);
      return ret;
    }

  /* Step 3: Initialize I2C */

  ret = gc2083_i2c_init();
  if (ret < 0)
    {
      GC2083_ERR("I2C init failed: %d", ret);
      return ret;
    }

  /* Step 4: Set I2C target address */

  putreg32(GC2083_I2C_ADDR, SG2000_I2C2_BASE + I2C_TAR);
  GC2083_DEBUG("I2C target address set to 0x%02X", GC2083_I2C_ADDR);

  /* Step 5: Read chip ID high byte */

  GC2083_DEBUG("Reading chip ID high byte (0x%04X)...", GC2083_CHIP_ID_H_REG);
  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
  if (ret < 0)
    {
      GC2083_ERR("Failed to read chip ID high byte: %d", ret);
      return ret;
    }

  GC2083_DEBUG("Chip ID High = 0x%02X", id_h);

  /* Step 6: Read chip ID low byte */

  GC2083_DEBUG("Reading chip ID low byte (0x%04X)...", GC2083_CHIP_ID_L_REG);
  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_L_REG, &id_l);
  if (ret < 0)
    {
      GC2083_ERR("Failed to read chip ID low byte: %d", ret);
      return ret;
    }

  GC2083_DEBUG("Chip ID Low = 0x%02X", id_l);

  /* Step 7: Combine and verify chip ID */

  chip_id = ((uint16_t)id_h << 8) | id_l;

  GC2083_INFO("========================================");
  GC2083_INFO("Chip ID Read Result:");
  GC2083_INFO("  Read:     0x%04X", chip_id);
  GC2083_INFO("  Expected: 0x%04X", GC2083_CHIP_ID);
  GC2083_INFO("========================================");

  if (chip_id == GC2083_CHIP_ID)
    {
      GC2083_INFO("GC2083 Sensor Detected Successfully!");
      return OK;
    }
  else
    {
      GC2083_WARN("Chip ID Mismatch! Sensor not detected.");
      return -ENODEV;
    }
}

