225	/****************************************************************************
226	 * Name: gc2083_i2c_init
227	 *
228	 * Description:
229	 *   Initialize I2C2 controller for GC2083 communication
230	 *
231	 ****************************************************************************/
232	
233	static int gc2083_i2c_init(void)
234	{
235	  uint32_t reg;
236	  int      timeout;
237	
238	  GC2083_INFO("Initializing I2C2 controller...");
239	
240	  /* Step 1: Enable I2C clock */
241	
242	  GC2083_DEBUG("Enabling I2C clock...");
243	
244	  /* Select clock source (osc = 25MHz) */
245	
246	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_BYP_0);
247	  reg |= (1 << 31);
248	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_BYP_0);
249	
250	  /* Set divider (divide by 1) */
251	
252	  reg = getreg32(SG2000_CLK_BASE + REG_DIV_CLK_I2C);
253	  reg &= ~(0xF << 16);
254	  reg |= (1 << 16);
255	  putreg32(reg, SG2000_CLK_BASE + REG_DIV_CLK_I2C);
256	
257	  /* Enable CLK_I2C */
258	
259	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_EN_3);
260	  reg |= (1 << 7);
261	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_EN_3);
262	
263	  GC2083_DEBUG("I2C clock enabled");
264	
265	  /* Step 2: Disable I2C controller */
266	
267	  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
268	
269	  /* Wait for controller to be disabled */
270	
271	  timeout = 1000;
272	  while (timeout-- > 0)
273	    {
274	      reg = getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS);
275	      if ((reg & 1) == 0)
276	        {
277	          break;
278	        }
279	
280	      gc2083_delay_ms(1);
281	    }
282	
283	  if (timeout <= 0)
284	    {
285	      GC2083_ERR("Failed to disable I2C controller");
286	      return -ETIMEDOUT;
287	    }
288	
289	  /* Step 3: Configure I2C controller
290	   * Master mode + Standard speed (100kHz) + Restart enable + Slave disable
291	   */
292	
293	  reg = I2C_CON_MASTER | I2C_CON_SPEED_STD |
294	        I2C_CON_RESTART_EN | I2C_CON_SLAVE_DISABLE;
295	  putreg32(reg, SG2000_I2C2_BASE + I2C_CON);
296	
297	  /* Step 4: Configure SCL timing for 100kHz
298	   * I2C clock = 25MHz
299	   * Standard mode: tHIGH = 4.0us, tLOW = 4.7us
300	   * HCNT = 25MHz * 4.0us = 100
301	   * LCNT = 25MHz * 4.7us = 117.5 ≈ 118
302	   */
303	
304	  putreg32(100, SG2000_I2C2_BASE + I2C_SS_SCL_HCNT);
305	  putreg32(118, SG2000_I2C2_BASE + I2C_SS_SCL_LCNT);
306	
307	  /* Step 5: Configure SDA hold time */
308	
309	  putreg32(0x1E, SG2000_I2C2_BASE + I2C_SDA_HOLD);
310	
311	  /* Step 6: Enable I2C controller */
312	
313	  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
314	
315	  GC2083_INFO("I2C2 controller initialized successfully");
316	
317	  return OK;
318	}
