396	           SG2000_I2C2_BASE + I2C_DATA_CMD);
397	
398	  /* Send read command with stop */
399	
400	  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);
401	
402	  putreg32(I2C_CMD_READ | I2C_CMD_STOP,
403	           SG2000_I2C2_BASE + I2C_DATA_CMD);
404	
405	  /* Wait for data */
406	
407	  ret = gc2083_i2c_wait_rx_data();
408	  if (ret < 0)
409	    {
410	      GC2083_ERR("Timeout waiting for I2C data");
411	      return ret;
412	    }
413	
414	  /* Read data */
415	
416	  *value = (uint8_t)(getreg32(SG2000_I2C2_BASE + I2C_DATA_CMD) & 0xFF);
417	
418	  return OK;
