/****************************************************************************
 * Name: gc2083_gpio_set_output
 *
 * Description:
 *   Set a GPIO pin on PORT C as output with specified value
 *
 ****************************************************************************/

static void gc2083_gpio_set_output(int pin, int value)
{
  uint32_t base = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
  uint32_t reg;

  /* Set as output (clear OEN bit) */

  reg = getreg32(base + GPIO_OEN);
  reg &= ~(1 << pin);
  putreg32(reg, base + GPIO_OEN);

  /* Set output value */

  reg = getreg32(base + GPIO_OUTPUT);
  if (value)
    {
      reg |= (1 << pin);
    }
  else
    {
      reg &= ~(1 << pin);
    }

  putreg32(reg, base + GPIO_OUTPUT);
}

