131	/****************************************************************************
132	 * Name: gc2083_gpio_set_output
133	 *
134	 * Description:
135	 *   Set a GPIO pin on PORT C as output with specified value
136	 *
137	 ****************************************************************************/
138	
139	static void gc2083_gpio_set_output(int pin, int value)
140	{
141	  uint32_t base = SG2000_GPIO_BASE + GPIO_PORT_C * 0x1000;
142	  uint32_t reg;
143	
144	  /* Set as output (clear OEN bit) */
145	
146	  reg = getreg32(base + GPIO_OEN);
147	  reg &= ~(1 << pin);
148	  putreg32(reg, base + GPIO_OEN);
149	
150	  /* Set output value */
151	
152	  reg = getreg32(base + GPIO_OUTPUT);
153	  if (value)
154	    {
155	      reg |= (1 << pin);
156	    }
157	  else
158	    {
159	      reg &= ~(1 << pin);
160	    }
161	
162	  putreg32(reg, base + GPIO_OUTPUT);
163	}
