178	/****************************************************************************
179	 * Name: gc2083_i2c_init
180	 *
181	 * Description:
182	 *   Initialize I2C2 controller for GC2083 communication
183	 *
184	 ****************************************************************************/
185	
186	static int gc2083_i2c_init(void)
187	{
188	  uint32_t reg;
189	  int      timeout;
190	
191	  GC2083_INFO("Initializing I2C2 controller...");
192	
193	  /* Step 1: Enable I2C clock */
194	
195	  GC2083_DEBUG("Enabling I2C clock...");
196	
197	  /* Select clock source (osc = 25MHz) */
198	
199	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_BYP_0);
200	  reg |= (1 << 31);
201	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_BYP_0);
202	
203	  /* Set divider (divide by 1) */
204	
205	  reg = getreg32(SG2000_CLK_BASE + REG_DIV_CLK_I2C);
206	  reg &= ~(0xF << 16);
207	  reg |= (1 << 16);
208	  putreg32(reg, SG2000_CLK_BASE + REG_DIV_CLK_I2C);
209	
210	  /* Enable CLK_I2C */
211	
212	  reg = getreg32(SG2000_CLK_BASE + REG_CLK_EN_3);
213	  reg |= (1 << 7);
214	  putreg32(reg, SG2000_CLK_BASE + REG_CLK_EN_3);
215	
216	  GC2083_DEBUG("I2C clock enabled");
217	
218	  /* Step 2: Disable I2C controller */
219	
220	  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
221	
222	  /* Wait for controller to be disabled */
223	
224	  timeout = 1000;
225	  while (timeout-- > 0)
226	    {
227	      reg = getreg32(SG2000_I2C2_BASE + I2C_ENABLE_STATUS);
228	      if ((reg & 1) == 0)
229	        {
230	          break;
231	        }
232	
233	      gc2083_delay_ms(1);
234	    }
235	
236	  if (timeout <= 0)
237	    {
238	      GC2083_ERR("Failed to disable I2C controller");
239	      return -ETIMEDOUT;
240	    }
241	
242	  /* Step 3: Configure I2C controller
243	   * Master mode + Standard speed (100kHz) + Restart enable + Slave disable
244	   */
245	
246	  reg = I2C_CON_MASTER | I2C_CON_SPEED_STD |
247	        I2C_CON_RESTART_EN | I2C_CON_SLAVE_DISABLE;
248	  putreg32(reg, SG2000_I2C2_BASE + I2C_CON);
249	
250	  /* Step 4: Configure SCL timing for 100kHz
251	   * I2C clock = 25MHz
252	   * Standard mode: tHIGH = 4.0us, tLOW = 4.7us
253	   * HCNT = 25MHz * 4.0us = 100
254	   * LCNT = 25MHz * 4.7us = 117.5 ≈ 118
255	   */
256	
257	  putreg32(100, SG2000_I2C2_BASE + I2C_SS_SCL_HCNT);
258	  putreg32(118, SG2000_I2C2_BASE + I2C_SS_SCL_LCNT);
259	
260	  /* Step 5: Configure SDA hold time */
261	
262	  putreg32(0x1E, SG2000_I2C2_BASE + I2C_SDA_HOLD);
263	
264	  /* Step 6: Enable I2C controller */
265	
266	  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
267	
268	  GC2083_INFO("I2C2 controller initialized successfully");
269	
270	  return OK;
271	}
