281	static int gc2083_i2c_wait_tx_empty(void)
282	{
283	  int timeout = 1000;
284	
285	  while (timeout-- > 0)
286	    {
287	      uint32_t status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
288	      if (status & I2C_STATUS_TFE)
289	        {
290	          return OK;
291	        }
292	
293	      gc2083_delay_ms(1);
294	    }
