308	{
309	  int timeout = 1000;
310	
311	  while (timeout-- > 0)
312	    {
313	      uint32_t status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
314	      if (status & I2C_STATUS_RFNE)
