325	/****************************************************************************
326	 * Name: gc2083_i2c_read_reg
327	 *
328	 * Description:
329	 *   Read a 16-bit register from GC2083
330	 *
331	 ****************************************************************************/
332	
333	static int gc2083_i2c_read_reg(uint16_t reg_addr, uint8_t *value)
334	{
335	  int ret;
336	
337	  /* Send register address high byte */
338	
339	  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);
340	
341	  putreg32(I2C_CMD_WRITE | ((reg_addr >> 8) & 0xFF),
342	           SG2000_I2C2_BASE + I2C_DATA_CMD);
343	
344	  /* Send register address low byte */
345	
346	  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);
347	
348	  putreg32(I2C_CMD_WRITE | (reg_addr & 0xFF),
349	           SG2000_I2C2_BASE + I2C_DATA_CMD);
350	
351	  /* Send read command with stop */
352	
353	  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);
354	
355	  putreg32(I2C_CMD_READ | I2C_CMD_STOP,
356	           SG2000_I2C2_BASE + I2C_DATA_CMD);
357	
358	  /* Wait for data */
359	
360	  ret = gc2083_i2c_wait_rx_data();
361	  if (ret < 0)
362	    {
363	      GC2083_ERR("Timeout waiting for I2C data");
364	      return ret;
365	    }
366	
367	  /* Read data */
368	
369	  *value = (uint8_t)(getreg32(SG2000_I2C2_BASE + I2C_DATA_CMD) & 0xFF);
370	
371	  return OK;
372	}
