440	/****************************************************************************
441	 * Name: gc2083_detect
442	 *
443	 * Description:
444	 *   Detect GC2083 sensor by reading chip ID via I2C
445	 *
446	 * Returned Value:
447	 *   OK if sensor detected successfully, negative errno otherwise
448	 *
449	 ****************************************************************************/
450	
451	int gc2083_detect(void)
452	{
453	  uint8_t id_h;
454	  uint8_t id_l;
455	  uint16_t chip_id;
456	  int ret;
457	
458	  GC2083_INFO("========================================");
459	  GC2083_INFO("GC2083 Sensor Detection Start");
460	  GC2083_INFO("========================================");
461	
462	  /* Step 1: Enable MCLK output (24MHz) on XGPIOC13 */
463	
464	  ret = gc2083_mclk_enable();
465	  if (ret < 0)
466	    {
467	      GC2083_ERR("MCLK enable failed: %d", ret);
468	      return ret;
469	    }
470	
471	  /* Step 2: Reset sensor via XGPIOC17 */
472	
473	  ret = gc2083_reset();
474	  if (ret < 0)
475	    {
476	      GC2083_ERR("Reset failed: %d", ret);
477	      return ret;
478	    }
479	
480	  /* Step 3: Initialize I2C2 controller */
481	
482	  ret = gc2083_i2c_init();
483	  if (ret < 0)
484	    {
485	      GC2083_ERR("I2C init failed: %d", ret);
486	      return ret;
487	    }
488	
489	  /* Step 4: Set I2C target address (GC2083 = 0x37) */
490	
491	  putreg32(GC2083_I2C_ADDR, SG2000_I2C2_BASE + I2C_TAR);
492	  GC2083_DEBUG("I2C target address set to 0x%02X", GC2083_I2C_ADDR);
493	
494	  /* Step 5: Read chip ID high byte from register 0x03F0 */
495	
496	  GC2083_DEBUG("Reading chip ID high byte (0x%04X)...", GC2083_CHIP_ID_H_REG);
497	  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
498	  if (ret < 0)
499	    {
500	      GC2083_ERR("Failed to read chip ID high byte: %d", ret);
501	      return ret;
502	    }
503	
504	  GC2083_DEBUG("Chip ID High = 0x%02X", id_h);
505	
506	  /* Step 6: Read chip ID low byte from register 0x03F1 */
507	
508	  GC2083_DEBUG("Reading chip ID low byte (0x%04X)...", GC2083_CHIP_ID_L_REG);
509	  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_L_REG, &id_l);
510	  if (ret < 0)
511	    {
512	      GC2083_ERR("Failed to read chip ID low byte: %d", ret);
513	      return ret;
514	    }
515	
516	  GC2083_DEBUG("Chip ID Low = 0x%02X", id_l);
517	
518	  /* Step 7: Combine and verify chip ID */
519	
520	  chip_id = ((uint16_t)id_h << 8) | id_l;
521	
522	  GC2083_INFO("========================================");
523	  GC2083_INFO("Chip ID Read Result:");
524	  GC2083_INFO("  Read:     0x%04X", chip_id);
525	  GC2083_INFO("  Expected: 0x%04X", GC2083_CHIP_ID);
526	  GC2083_INFO("========================================");
527	
528	  if (chip_id == GC2083_CHIP_ID)
529	    {
530	      GC2083_INFO("GC2083 Sensor Detected Successfully!");
531	      return OK;
532	    }
533	  else
534	    {
535	      GC2083_WARN("Chip ID Mismatch! Sensor not detected.");
536	      return -ENODEV;
537	    }
538	}
