{
  uint32_t reg;

  GC2083_INFO("Enabling MCLK output (24MHz)...");

  /* Step 1: Configure Pinmux for XGPIOC13 as CAM_MCLK0
   * Pinmux Register: 0x03001000 + offset for MIPI_TXP1
   * Function: CAM_MCLK0
   *
   * Note: This should ideally be done in board initialization
   * but we do it here for completeness
   */

  /* Step 2: Configure MCLK clock source and divider
   * CAM_MCLK0 clock tree:
   *   Source: CAM0PLL or OSC
   *   Divider: to produce 24MHz
   *
   * For 24MHz from OSC (25MHz):
   *   We need fractional divider or use CAM0PLL
   *
   * Register: REG_CAM_MCLK_CTRL (0x03002090)
   *   - Select clock source
   *   - Set divider
   */

  /* Enable CAM0 clock in clock gate register */
  reg = getreg32(SG2000_CLK_BASE + 0x008);  /* REG_CLK_EN_2 */
  reg |= (1 << 16);  /* Enable CAM0 clock */
  putreg32(reg, SG2000_CLK_BASE + 0x008);

  /* Configure CAM_MCLK output
   * The MCLK register controls the output frequency
   * We need to set it to produce 24MHz
   */

  /* Set MCLK divider to produce 24MHz from source
   * If source is 96MHz (CAM0PLL), divider = 4
   * If source is 25MHz (OSC), we need fractional divider
   */

  /* Configure MCLK control register */
  putreg32(0x04, SG2000_CLK_BASE + 0x090);  /* Set MCLK divider */

  GC2083_DEBUG("MCLK output enabled on XGPIOC13 (24MHz)");

  return OK;
}

