static int gc2083_i2c_read_reg(uint16_t reg_addr, uint8_t *value)
{
  int ret;

  /* Send register address high byte */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

  putreg32(I2C_CMD_WRITE | ((reg_addr >> 8) & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send register address low byte */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

  putreg32(I2C_CMD_WRITE | (reg_addr & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send read command with stop */

  while ((getreg32(SG2000_I2C2_BASE + I2C_STATUS) & I2C_STATUS_TFNF) == 0);

