static int gc2083_i2c_read_reg(uint16_t reg_addr, uint8_t *value)
{
  int ret;
  uint32_t status;
  int timeout;

  GC2083_DEBUG("I2C read reg 0x%04X...", reg_addr);

  /* Check I2C status before transfer */

  status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
  GC2083_DEBUG("I2C status before transfer: 0x%08X", status);

  /* Check if I2C is active */

  if (status & I2C_STATUS_ACTIVITY)
    {
      GC2083_DEBUG("I2C is active");
    }

  /* Send register address high byte */

  timeout = 100;
  while (timeout-- > 0)
    {
      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      if (status & I2C_STATUS_TFNF)
        {
          break;
        }
    }

  if (timeout <= 0)
    {
      GC2083_ERR("TX FIFO full when sending addr high");
      return -ETIMEDOUT;
    }

  putreg32(I2C_CMD_WRITE | ((reg_addr >> 8) & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send register address low byte */

  timeout = 100;
  while (timeout-- > 0)
    {
      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      if (status & I2C_STATUS_TFNF)
        {
          break;
        }
    }

  if (timeout <= 0)
    {
      GC2083_ERR("TX FIFO full when sending addr low");
      return -ETIMEDOUT;
    }

  putreg32(I2C_CMD_WRITE | (reg_addr & 0xFF),
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Send read command with stop */

  timeout = 100;
  while (timeout-- > 0)
    {
      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      if (status & I2C_STATUS_TFNF)
        {
          break;
        }
    }

  if (timeout <= 0)
    {
      GC2083_ERR("TX FIFO full when sending read cmd");
      return -ETIMEDOUT;
    }

  putreg32(I2C_CMD_READ | I2C_CMD_STOP,
           SG2000_I2C2_BASE + I2C_DATA_CMD);

  /* Wait for data with timeout */

  ret = gc2083_i2c_wait_rx_data();
  if (ret < 0)
    {
      status = getreg32(SG2000_I2C2_BASE + I2C_STATUS);
      GC2083_ERR("Timeout waiting for I2C data, status=0x%08X", status);

      /* Check for NACK or other errors */

      uint32_t tx_abrt = getreg32(SG2000_I2C2_BASE + 0x80);
      GC2083_ERR("TX_ABRT_SOURCE = 0x%08X", tx_abrt);

      return ret;
    }

  /* Read data */

  *value = (uint8_t)(getreg32(SG2000_I2C2_BASE + I2C_DATA_CMD) & 0xFF);
  GC2083_DEBUG("I2C read value = 0x%02X", *value);

  return OK;
}

