int gc2083_detect(void)
{
  uint8_t id_h;
  uint8_t id_l;
  uint16_t chip_id;
  int ret;

  GC2083_INFO("========================================");
  GC2083_INFO("GC2083 Sensor Detection Start");
  GC2083_INFO("========================================");

  /* Step 1: Enable MCLK output (24MHz) on XGPIOC13 */

  ret = gc2083_mclk_enable();
  if (ret < 0)
    {
      GC2083_ERR("MCLK enable failed: %d", ret);
      return ret;
    }

  /* Step 2: Reset sensor via XGPIOC17 */

  ret = gc2083_reset();
  if (ret < 0)
    {
      GC2083_ERR("Reset failed: %d", ret);
      return ret;
    }

  /* Step 3: Initialize I2C2 controller */

  ret = gc2083_i2c_init();
  if (ret < 0)
    {
      GC2083_ERR("I2C init failed: %d", ret);
      return ret;
    }

  /* Step 4: Set I2C target address
   * IMPORTANT: IC_TAR can only be written when I2C controller is disabled
   * We need to disable -> set TAR -> re-enable
   */

  /* Disable I2C controller first */
  putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
  gc2083_delay_ms(1);

  /* Set target address */
  putreg32(GC2083_I2C_ADDR, SG2000_I2C2_BASE + I2C_TAR);
  GC2083_DEBUG("I2C target address set to 0x%02X", GC2083_I2C_ADDR);

  /* Re-enable I2C controller */
  putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
  gc2083_delay_ms(1);

  /* Step 5: Read chip ID high byte from register 0x03F0 */

  GC2083_DEBUG("Reading chip ID high byte (0x%04X)...", GC2083_CHIP_ID_H_REG);
  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
  if (ret < 0)
    {
      GC2083_ERR("Failed to read chip ID high byte: %d", ret);

      /* Try with 8-bit address (0x6E) as fallback */
      GC2083_INFO("Trying with 8-bit address 0x6E...");

      /* Disable I2C controller */
      putreg32(0, SG2000_I2C2_BASE + I2C_ENABLE);
      gc2083_delay_ms(1);

      /* Set 8-bit address */
      putreg32(GC2083_I2C_ADDR_8BIT, SG2000_I2C2_BASE + I2C_TAR);
      GC2083_DEBUG("I2C target address set to 0x%02X (8-bit)", GC2083_I2C_ADDR_8BIT);

      /* Re-enable I2C controller */
      putreg32(1, SG2000_I2C2_BASE + I2C_ENABLE);
      gc2083_delay_ms(1);

      /* Retry read */
      ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_H_REG, &id_h);
      if (ret < 0)
        {
          GC2083_ERR("Failed with 8-bit address too: %d", ret);
          return ret;
        }
    }

  GC2083_DEBUG("Chip ID High = 0x%02X", id_h);

  /* Step 6: Read chip ID low byte from register 0x03F1 */

  GC2083_DEBUG("Reading chip ID low byte (0x%04X)...", GC2083_CHIP_ID_L_REG);
  ret = gc2083_i2c_read_reg(GC2083_CHIP_ID_L_REG, &id_l);
  if (ret < 0)
    {
      GC2083_ERR("Failed to read chip ID low byte: %d", ret);
      return ret;
    }

  GC2083_DEBUG("Chip ID Low = 0x%02X", id_l);

  /* Step 7: Combine and verify chip ID */

  chip_id = ((uint16_t)id_h << 8) | id_l;

  GC2083_INFO("========================================");
  GC2083_INFO("Chip ID Read Result:");
  GC2083_INFO("  Read:     0x%04X", chip_id);
  GC2083_INFO("  Expected: 0x%04X", GC2083_CHIP_ID);
  GC2083_INFO("========================================");

  if (chip_id == GC2083_CHIP_ID)
    {
      GC2083_INFO("GC2083 Sensor Detected Successfully!");
      return OK;
    }
  else
    {
      GC2083_WARN("Chip ID Mismatch! Sensor not detected.");
      return -ENODEV;
    }
}

